   "scale_text": "团队规模由巅峰期约 130 人收缩至含实习生在内的 70 余人，差额约 60 人；报道称「新一轮优化仍在进行中」。这是两个时点的团队规模对比（含主动离职、核心高管出走与离职不补），不是公司披露的单次裁员人数；且 70 余人含实习生，与 130 人口径未必一致。另据微信公众号「具身涌现观察」援引企查查，2025 年社保参保人数为 23 人，与报道人数在时点、范围上均不一致，不采信、不换算",
