   "pct_num": null,
   "reason": "具身智能赛道融资退潮叠加自身商业化与现金流承压：公司 2024 年 9 月由原小米汽车自动驾驶产品技术负责人刘方创立，公开融资仅 2025 年两轮（安克创新领投亿元级种子轮，跟投含险峰长青、欣旺达、中金资本等）；2026 年上半年具身融资总额刷新纪录，但公司始终未披露新融资。据知情人士，孵化方兼种子轮领投方安克创新「不想再继续加注」，原因与具身商业化周期较长、公司现金流「出了一点问题」有关；另有行业人士称其产品能力与商业化进度未跟上赛道节奏、工业场景需尽快找到可批量交付的场景。核心团队集体出走被该知情人士部分归因于 CEO 刘方的管理风格。属融资断档＋订单转化不及预期驱动的组织收缩，非单一降本动作，亦非公司关停——一家参投机构明确表示「阿米奥现在还在正常运营」",
   "status": "rumor",
   "verify": "部分核实",
   "summary": "11 月 11 日 21:45，观点网首发（腾讯新闻、新浪财经、网易等多源转载）：由安克创新孵化、原小米汽车自动驾驶产品技术负责人刘方创立的工业具身智能公司阿米奥机器人，正经历核心团队出走与组织收缩，原 CTO、COO 与产品负责人均已离职，团队规模从巅峰期约 130 人收缩至含实习生在内的 70 余人，且新一轮优化仍在进行中。报道援引知情人士称，孵化方兼种子轮领投方安克创新不愿继续加注，与具身商业化周期较长、公司现金流出现问题有关；核心团队集体出走被部分归因于 CEO 管理风格。公司未就本轮人员调整发布公告或正式回应，但一家参投机构表示公司「还在正常运营」。行业背景：2026 年工业机器人公司进入洗牌期，盈合机器人、深兰机器人（上海）先后进入破产清算，南京无境未来动力创始人失联并拖欠薪资。公司未披露本轮优化的裁员人数、占员工总数比例、涉及部门与补偿方案。属上次运行（11-11 09:19）之后窗口内首次公开，本次按增量补录。",
   "source_name": "观点网 2026-11-11 21:45《阿米奥机器人团队规模收缩至 70 余人 核心团队相继离职》；腾讯新闻 2026-11-11 转载 / 新浪财经 / 网易 / 企查查 / 微信公众号「具身涌现观察」交叉",
