   "summary": "11 月 11 日，路透社报道（彭博社、Front Office Sports 同步，新浪财经 11-12 中文转载）：美国预测市场平台 Polymarket 已裁减部分员工并终止若干承包商合同。上周起在社交平台 X 流传的一封内部邮件显示，公司「作为公司整体裁员计划的一部分」决定终止某承包合同，自 2026 年 11 月 4 日起生效；公司于周三（11 月 11 日）向媒体确认该邮件截图属实，并在电子邮件声明中称随公司发展与新领导层到位进行了重组，涉及大量新招聘、人事变动以及部分人员离职。公司拒绝披露裁员人数及占员工总数比例，一位知情人士向路透表示被裁人员中超过 50% 为合同工。背景：Polymarket 月度交易额已被 Kalshi 反超；公司 9 月任命首任 CFO Warren Jenson、年内引入前 Uber 高管任首席增长官；CFTC 正就其是否违反 2022 年执法和解协议展开调查。公司未披露补偿方案。属上次运行（11-11 09:19）之后窗口内首次公开，本次按增量补录。",
