   "reason": "大客户车型量产推迟一年导致预期回款延后、收入指引大幅下调：公司 Q3 2026 营收 1210 万美元（上年同期 1530 万美元），运营费用 1970 万美元、同比增 9%，截至 9 月末流动性约 5440 万美元、季度现金消耗约 1500 万美元；公司将 FY2026 收入目标下调至 4400 万—4600 万美元，并称因转向国防市场不再就新项目中标数 / NRE 付款计划提供指引。核心驱动是一家主要汽车客户搭载其传感器的车型上市推迟一年，使公司原预期收到的款项延后；叠加与大众、宝马等车企合同执行延后、多次未达此前收入指引，股价年内下跌 74%，市值由 2021 年 SPAC 上市时的 14 亿美元缩至约 6500 万—6600 万美元。公司同步把资源转向国防 / 反无人机（Perciz 品牌）等新方向。这是客户量产节奏＋现金跑道压力驱动，而非公司关停；且为近年第三轮裁员（2024 年约 13%、2025 年约 9%—10%），不与前两轮合并",
   "status": "confirmed",
