   "summary": "11 月 11 日，Innoviz Technologies 在 2026 年第三季度财报新闻稿中宣布，作为重组举措的一部分公司员工规模将缩减约 20%，预计带来约 1750 万美元年化成本节省；同日 CTech（Calcalist）、Globes 等以色列媒体报道约 80—90 名员工受影响、裁员后团队将不足 300 人，但两家媒体数字不一致且均非公司披露。公司 Q3 营收 1210 万美元、运营费用同比增 9%，并将 FY2026 收入目标下调至 4400 万—4600 万美元；主因是一家主要汽车客户搭载其激光雷达的车型上市推迟一年，导致预期回款延后，叠加与大众、宝马等车企合同执行延迟。公司未披露裁员绝对人数、裁员后员工总数与补偿方案。这是公司近年第三轮裁员（2024、2025 已有两轮）。属上次运行（11-11 09:19）之后窗口内首次公开，本次按增量补录。",
