   "pct_num": null,
   "reason": "澳航与埃森哲达成多年期战略合作，推进后台系统、业务流程与数据平台现代化并加大人工智能投资，部分企业职能改由埃森哲（主要由印度团队及部分澳大利亚团队）提供，后续进一步引入自动化与 AI。CEO 凡妮莎·哈德森（Vanessa Hudson）在致员工信中称目的是「现代化业务背后的技术、提升效率，以便持续投资客户、员工与未来」，并强调「这一领域变化的规模与速度前所未有，全球领先组织已在用技术与 AI 彻底改造工作方式，原地不动不是选项」，同时就调整带来的不确定性向员工致歉。公司 8 月公布的 2025/26 财年净利润 13 亿澳元、同比下降 19.8%，基础税前利润降 13.8%，燃油成本高企亦有影响，但公司本次明确把驱动因素归于技术现代化与效率提升，且承诺与工会协商、尽可能转岗与再培训，并非以直接裁撤降本为唯一目标",
   "status": "confirmed",
   "verify": "已核实",
   "summary": "11 月 10 日，澳洲航空集团（Qantas Group）宣布与埃森哲（Accenture）达成多年期战略合作，推进后台系统、业务流程和数据平台现代化，并加大人工智能投资。合作将涉及企业职能调整，部分服务转由埃森哲提供，主要由其印度团队及部分澳大利亚团队负责，后续进一步引入自动化与人工智能。澳航预计，未来数年集团约 850 个岗位将受到影响，首批调整预计于 2027 年年中前实施；公司表示将与受影响员工及工会协商，并尽可能安排转岗、提供再培训和其他支持。AAP 报道称首批调整涉及财务、采购、人力资源与市场营销岗位，CEO 凡妮莎·哈德森在致员工邮件中就调整带来的不确定性致歉，并称变化是为「现代化业务背后的技术、提升效率」，提到 AI 与自动化带来的工作方式变革。中文由东方财富网、新浪财经 7×24、腾讯新闻于 11 月 10 日交叉转述，口径统一为「约 850 个岗位将受影响」；英文 AAP 稿以「nearly 1000 jobs」为标题并称含大规模强制裁员。公司未披露实际裁员人数、占集团员工总数比例、各部门净减明细与补偿方案。属上次运行（11-09 09:20）之后窗口内首次公开，本次按增量补录。",
   "source_name": "澳洲航空集团 2026-11-10 公告 / AAP News 2026-11-10；东方财富网 2026-11-10《澳航与埃森哲达成多年期战略合作，未来数年约850个岗位将受影响》、新浪财经 7×24 快讯 2026-11-10、腾讯新闻 2026-11-10 中文交叉",
