   "summary": "Eurogamer 于 11 月 7 日 21:06（GMT+1，北京时间 11 月 8 日）报道，《星球大战：零号连队》开发商 Bit Reactor 裁撤了一批员工，受影响人数未对外说明，工作室也未发布正式公告或回应。11 月 6 日（周五）多名开发者在领英宣布自己被裁，由 Bespin Bulletin 最先报道：其中包括高级环境美术师 Ryan Lopez，他在该项目工作三年半、从前期制作一路做到发售，结束三个月停薪留职后仍被裁；负责游戏战术任务大量界面 UI 的工程师 Tyler Eichten、QA 团队 Ryan Mosher 也确认离职。Lopez 写道「虽然这很痛，但我真的为我们一起做出来的东西感到骄傲」。背景链条：游戏 8 月 27 日发售前数周，Bit Reactor 让大部分员工停薪留职（有消息源给出约 80% 的比例），工作室看似在临近发售时资金已见底；但游戏发售一个月内销量据信超过 100 万份，Eurogamer 评测给出四星。10 月 7 日 CEO Greg Foertsch 在 Bluesky 发文称已启动让更多团队成员返岗的流程，据信回归人数超过工作室半数、但并非所有人都恢复全额薪资。目前不清楚本轮被裁人员中是否包含刚返岗的员工，工作室也未说明裁员是否影响游戏后续更新计划。腾讯新闻 / IT时代网、网易等于 11 月 8 日中文交叉转述。",
