   "summary": "11 月 5 日，澳大利亚 AI 临床笔记公司 Heidi Health 的 CEO 兼联合创始人 Thomas Kelly 在全员会与致员工信中宣布裁减约 18% 全球员工，理由是需要「围绕能为客户带来最大影响、支撑增长的市场与投资重新平衡团队」。AFR 首发、Brisbane Times 全文转载，MobiHealthNews、Medical Republic、Startup Daily 等交叉报道。公司未直接公布绝对人数，媒体按 600 余名员工折算为约 108 个岗位；据 AFR，削减集中在墨尔本研发、客户支持与销售团队，部分岗位转往境外。Kelly 对 AFR 承认对医院与大型医疗系统的采购速度「过于乐观」、提前超配了企业级岗位，并称投资人希望业务更可预测。裁员前一天，联合创始人 CTO Yu Liu 与 CFO Waleed Mussa 宣布退出运营岗位（Liu 转任顾问至 2027 年 3 月）。公司 9 月刚完成由 Blackbird 领投的 1 亿美元 C 轮及 General Catalyst 提供的 2.4 亿美元增长融资，估值约 12.6 亿澳元；领投方 Blackbird 公开表示支持这一决定并将协助受影响员工找工作。公司称遣散与福利高于各国法定标准、按国家而异，同时仍在招聘关键岗位；每周支持约 280 万至 300 万次患者交互、业务覆盖 190 余个国家。同期公司还与 GP 软件商 Best Practice 就 Heidi II 与 Bp Premier 的许可兼容性公开争执。",
