   "summary": "据腾讯新闻 11 月 3 日转越南中文社推送，位于胡志明市宝旁工业区的 ECCO 越南有限责任公司于 11 月 2 日下午向劳动者宣布：公司所有者已决定依规解散公司，并办理终止在越南生产经营的相关法律手续；劳动合同将于 2026 年 11 月 30 日终止，自 11 月 3 日起至终止日员工无需到办公室或工厂上班。据 2025 年劳动者会议记录，该工厂有 1620 名工人。公司承诺足额、按时支付工资及各项应得权益，并在法定款项之外额外支付一笔补助以认可员工服务年限，同时完成社保、失业保险参保时间确认并退还社保册。宝旁乡人民委员会领导证实当天下午企业总经理已与劳动者开会通报；胡志明市出口加工区和工业区管理委员会（HEPZA）副主席张文峰向媒体表示，ECCO 越南主张停止在越活动以集中扩建丹麦主要工厂，企业承诺履行工资与员工制度义务，目前未记录到社保欠缴，管委会已会同工会就劳动者权益与企业沟通并将对接周边有招聘需求的企业帮助工人再就业。",
